def gcd(a,b):
    if b==0:
        return a
    else:
        return gcd(b,a%b)
def answer(x,y): 
    l = x*y//gcd(x,y)
    while True:
        if l>=x and l<=y:
            break
        l+=1
    return (l,x*l//y)
