def rearrange_bigger(n): 
    arr = [int(i) for i in str(n)] 
    n = len(arr)
    if n == 1 or n == 0: 
        return False
    else: 
        for i in range(n-1):
            for j in range(i+1,n):
                if arr[i] < arr[j]:
                    temp = arr[i]
                    arr[i] = arr[j]
                    arr[j] = temp
                    break
        s = ''.join(map(str,arr))
        if int(s) > n:
            return True
        else:
            return False
```

